import { type Plugin } from "@opencode-ai/plugin";

export default (async () => {
  return {
    "tool.definition": async (input, output) => {
      // Напоминание о CYCLE 4 для КАЖДОГО инструмента (prevention-уровень)
      const cycleNote = "\n\n⚠️ После использования (если задача ВЫПОЛНЕНА): VERIFY → автоматически CYCLE 4 LEARN.";

      // Добавляем напоминание, если его ещё нет
      if (output.description && !output.description.includes("CYCLE 4")) {
        output.description += cycleNote;
      }

      // Для bash — расширенные ограничения + напоминание
      if (input.toolID === "bash") {
        const restrictions =
          "\n\nДОСТУПНЫЕ КОМАНДЫ:\n"
          + "  fd, rg, bun, bunx — быстрые аналоги find, grep, npm, npx\n"
          + "  ls, cat, echo, pwd, curl, mkdir, rm (осторожно), cp, mv, cd\n"
          + "  head, tail, wc, sort, uniq, tee, xargs, printf, test\n"
          + "  git, docker, doas, chmod, chown\n"
          + "  ps, df, du, free, uname, whoami, id, uptime\n"
          + "  python3, node, nvim\n\n"
          + "ЗАПРЕЩЕНЫ: find (→ fd), grep (→ rg), npm (→ bun), npx (→ bunx), glob (→ fd)";

        // Полностью заменяем описание bash
        output.description =
          "Execute shell commands in a restricted environment."
          + restrictions
          + cycleNote;
      }
    },

    "experimental.chat.system.transform": async (input, output) => {
      // Warm Refresh — вставляется в начало system prompt каждую сессию
      const warmRefresh =
        "[WARM REFRESH]\n"
        + "✅ CYCLE 1 на КАЖДОЕ сообщение — нет исключений\n"
        + "✅ RECALL — только при неуверенности\n"
        + "✅ VERIFY → задача выполнена → CYCLE 4 LEARN\n"
        + "✅ CYCLE 4 — только ПОСЛЕ задачи (не на простых вопросах)\n"
        + "[/WARM REFRESH]\n\n";

      if (output.system) {
        // Вставляем в самое начало, если там ещё нет
        if (!output.system.startsWith("[WARM REFRESH]")) {
          output.system = warmRefresh + output.system;
        }
      }
    },
  };
}) satisfies Plugin;
